package com.tsk.trofeomirror
import android.app.*;import android.content.*;import android.graphics.*;import android.hardware.display.DisplayManager;import android.media.ImageReader;import android.media.projection.*;import android.os.*;import androidx.core.app.NotificationCompat;import okhttp3.*;import okhttp3.MediaType.Companion.toMediaType;import okhttp3.RequestBody.Companion.toRequestBody;import java.io.ByteArrayOutputStream;import java.util.concurrent.Executors
class MirrorService:Service(){private var mp:MediaProjection?=null;private var reader:ImageReader?=null;private var vd:android.hardware.display.VirtualDisplay?=null;private val ex=Executors.newSingleThreadExecutor();private val http=OkHttpClient();private var ip=""
override fun onBind(i:Intent?)=null
override fun onStartCommand(i:Intent?,f:Int,id:Int):Int{ip=i?.getStringExtra("ip")?:"172.19.95.220";val nm=getSystemService(NOTIFICATION_SERVICE) as NotificationManager;nm.createNotificationChannel(NotificationChannel("trofeo","TROFEO Mirror",NotificationManager.IMPORTANCE_LOW));startForeground(1,NotificationCompat.Builder(this,"trofeo").setContentTitle("TROFEO Mirror").setContentText("Streaming screen").setSmallIcon(android.R.drawable.ic_media_play).build());val code=i!!.getIntExtra("code",Activity.RESULT_CANCELED);@Suppress("DEPRECATION") val data=i.getParcelableExtra<Intent>("data")!!;val mgr=getSystemService(MEDIA_PROJECTION_SERVICE) as MediaProjectionManager;mp=mgr.getMediaProjection(code,data);reader=ImageReader.newInstance(1280,480,PixelFormat.RGBA_8888,2);vd=mp!!.createVirtualDisplay("Trofeo",1280,480,240,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,reader!!.surface,null,null);reader!!.setOnImageAvailableListener({r->val image=r.acquireLatestImage()?:return@setOnImageAvailableListener;try{val p=image.planes[0];val pad=p.rowStride-p.pixelStride*image.width;val raw=Bitmap.createBitmap(image.width+pad/p.pixelStride,image.height,Bitmap.Config.ARGB_8888);raw.copyPixelsFromBuffer(p.buffer);val bm=Bitmap.createBitmap(raw,0,0,image.width,image.height);raw.recycle();ex.execute{val o=ByteArrayOutputStream();bm.compress(Bitmap.CompressFormat.JPEG,40,o);bm.recycle();val q=Request.Builder().url("http://$ip:8765/frame").post(o.toByteArray().toRequestBody("image/jpeg".toMediaType())).build();try{http.newCall(q).execute().close()}catch(_:Exception){}}}finally{image.close()}},Handler(Looper.getMainLooper()));return START_NOT_STICKY}
override fun onDestroy(){reader?.close();vd?.release();mp?.stop();ex.shutdownNow();super.onDestroy()}}